239	// 重复，打开、查询与后续写入一切正常。
240	func TestEmptyRequestsObjectStillUsable(t *testing.T) {
241		for name, requests := range map[string]string{
242			"空对象": `{}`,
243			"null": `null`,
244		} {
245			t.Run(name, func(t *testing.T) {
246				dir := t.TempDir()
247				data := []byte(`{"version":1,"recipes":[],"batches":[],"requests":` + requests + `}`)
248				if err := os.WriteFile(filepath.Join(dir, stateFileName), data, 0o644); err != nil {
249					t.Fatal(err)
250				}
251				s, err := Open(dir)
252				if err != nil {
253					t.Fatalf("没有成功请求记录的空台账应能打开: %v", err)
254				}
255				defer s.Close()
256				if _, err := s.GetBatch("B1"); !errors.Is(err, ErrNotFound) {
257					t.Fatalf("空台账查询批次应返回 ErrNotFound，得到 %v", err)
258				}
259				registerStandardRecipe(t, s, "recipe-1")
260				if _, err := s.GetRecipe("R1", "v1"); err != nil {
261					t.Fatalf("空台账应可正常写入并查询: %v", err)
262				}
263			})
264		}
265	}
