package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

type T struct {
	Requests int `json:"requests"`
}

func main() {
	// 各种键：开尔文符号替换 K、全角等，看 json 是否映射到 requests，
	// 再与 strings.EqualFold 的判断对比。
	keys := []string{
		"Requests", "REQUESTS", "ReQuEsTs",
		"requests",
		"K" + "requests", // 普通 K 大写
		"K" + "requests", // 开尔文符号 U+212A（若环境保留）
		"рequests",       // 西里尔 р
	}
	for _, k := range keys {
		src := `{"` + k + `":7}`
		var t T
		err := json.Unmarshal([]byte(src), &t)
		jsonMatch := err == nil && t.Requests == 7
		eq := strings.EqualFold(k, "requests")
		flag := ""
		if jsonMatch != eq {
			flag = "  <<< 不一致!"
		}
		fmt.Printf("key=%q json映射到requests=%v EqualFold=%v%s\n", k, jsonMatch, eq, flag)
	}
}
EOF
go run fold2.go; rm -f fold2.go fold_check.go

