package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

type T struct {
	Requests int `json:"requests"`
}

func main() {
	// 用码位构造："reque" + U+017F(长s) + "ts"，避免传输层改写。
	k := "reque" + string(rune(0x017F)) + "ts"
	src := `{"` + k + `":7}`
	var t T
	err := json.Unmarshal([]byte(src), &t)
	fmt.Printf("key bytes=%q json err=%v mapped=%v EqualFold=%v\n",
		k, err, t.Requests == 7, strings.EqualFold(k, "requests"))
}
EOF
